project-responsive.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.site-header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid #cbded7;
}
.site-name { margin: 0; font-weight: 600; }
.site-nav { display: flex; flex-wrap: wrap; gap: 12px; }
.details { display: grid; gap: 16px; }
.detail-card { padding: 12px; border-radius: 8px; background: #eaf4f0; }
.detail-card h2 { margin: 0; font-size: 1.125rem; }
.detail-card p { margin: .5em 0 0; }
.site-footer p { margin-bottom: 0; }

/* 在这里添加宽屏规则。 */

@media (width >= 680px) {
  .site-header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
  .details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
